:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #eaeaea;
  --muted: #8899aa;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  color: var(--highlight);
}

.score {
  font-size: 1.125rem;
  color: var(--muted);
}

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--bg);
  border-radius: 8px;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  text-align: center;
}

.overlay.hidden {
  display: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.overlay-content h2 {
  font-size: 1.25rem;
  color: var(--highlight);
}

.overlay-content p {
  color: var(--muted);
  line-height: 1.5;
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  color: var(--text);
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--highlight);
}

.btn:focus-visible {
  outline: none;
  border-color: var(--highlight);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.35);
}

.btn:active {
  transform: scale(0.97);
  background: var(--highlight);
}

.btn.primary {
  background: var(--highlight);
}

.btn.primary:hover {
  background: #c73550;
}

.hint {
  text-align: center;
  font-size: 0.875rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 12px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK = 140;

  let snake, dir, nextDir, food, score, state, timer;

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = dir;
    score = 0;
    state = 'paused';
    scoreEl.textContent = 'Score: 0';
    placeFood();
    stopTimer();
    showOverlay('How to Play', 'Use arrow keys to move.<br>Press Start Game to begin.', 'Start Game');
    pauseBtn.textContent = 'Pause';
    draw();
  }

  function placeFood() {
    let p;
    do {
      p = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === p.x && s.y === p.y));
    food = p;
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.innerHTML = title;
    overlayText.innerHTML = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(tick, TICK);
  }

  function stopTimer() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  function play() {
    if (state === 'over') return;
    state = 'playing';
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    startTimer();
  }

  function pause() {
    if (state !== 'playing') return;
    state = 'paused';
    stopTimer();
    pauseBtn.textContent = 'Resume';
    showOverlay('Paused', 'Press Resume or P to continue.', 'Resume');
  }

  function togglePause() {
    if (state === 'playing') pause();
    else if (state === 'paused') play();
  }

  function gameOver() {
    state = 'over';
    stopTimer();
    pauseBtn.textContent = 'Pause';
    showOverlay('Game Over', 'Final score: ' + score + '<br>Press Restart to play again.', 'Restart');
  }

  function tick() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      draw();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = 'Score: ' + score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    snake.forEach((s, i) => {
      ctx.fillStyle = i === 0 ? '#eaeaea' : '#8899aa';
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function setDirection(x, y) {
    if (state !== 'playing') return;
    if (dir.x === -x && dir.y === -y) return;
    nextDir = { x, y };
  }

  document.addEventListener('keydown', function (e) {
    switch (e.key) {
      case 'ArrowUp':
        e.preventDefault();
        setDirection(0, -1);
        break;
      case 'ArrowDown':
        e.preventDefault();
        setDirection(0, 1);
        break;
      case 'ArrowLeft':
        e.preventDefault();
        setDirection(-1, 0);
        break;
      case 'ArrowRight':
        e.preventDefault();
        setDirection(1, 0);
        break;
      case 'p':
      case 'P':
        togglePause();
        break;
    }
  });

  pauseBtn.addEventListener('click', togglePause);

  restartBtn.addEventListener('click', function () {
    reset();
  });

  overlayBtn.addEventListener('click', function () {
    if (state === 'over') reset();
    else play();
  });

  reset();
})();
